\label{Lemma:EnoughRotational}
	Let $n\geq 2$, $q\in\{1,\ldots,n-1\}$,  $\gamma\in\{0,\ldots,q-1\}$, a rotation invariant measure $\tilde \mu_{n-q+\gamma}$ on $A(n,n-q+\gamma)$ and a rotation invariant function $J:A(n, \gamma) \rightarrow [0, \infty)$ be given. Then 
	\begin{equation}\label{eq:lemma21}
		\int_{G(n,q)}   \int_{A(n,n-q+\gamma)} f(E \cap L) 
		\ \tilde \mu_{n-q+\gamma}(dE) \ \nu (dL)
		=
		\int_{A(n,\gamma)} f(E) \ J(E) \ \mu_\gamma (dE)
	\end{equation}
    holds for all measurable functions $f : A(n , \gamma) \rightarrow [0,\infty)$, if it holds for those $f$ that are in addition rotation invariant.

Suppose that \eqref{eq:lemma21} holds true for all non-negative, measurable and rotation invariant functions. Fix an arbitrary measurable function $f:A(n,q) \rightarrow [0,\infty)$. Using the rotation invariance of the measures $\tilde\mu_{n-q+\gamma}$ and $\nu_q$ and Tonelli's theorem, the left-hand side of \eqref{eq:lemma21} is 
   \begin{align*}
		&\int_{SO_n}
	\int_{G(n,q)}   \int_{A(n,n-q+\gamma)} f(\eta^{-1}(E \cap L)) 
		\ \tilde\mu_{n-q+\gamma}(dE) \ \nu_q (dL)
      \nu(d\eta)
		\\&=
		\int_{G(n,q)}   \int_{A(n,n-q+\gamma)}  f_{\mbox{\small rot}}( E)
		\ \tilde\mu_{n-q+\gamma}(dE) \ \nu_q (dL). 
	\end{align*} 
   Using the rotation invariance of 
   $\mu_\gamma$ and $J$, a similar argument shows that the right-hand side of \eqref{eq:lemma21} is 
	\begin{align*}
		\int_{A(n,\gamma)} 
          f_{\mbox{\small rot}}(E) 
          J(E) \, \mu_\gamma (dE). 
	\end{align*}
	By assumption,  \eqref{eq:lemma21} holds for the rotation invariant function $f_{\mbox{\small rot}}$, so the last two displayed expressions coincide and the assertion is shown.

\label{Lemma:IntegralSubspaceDet}
	Let $n\geq 2$, $\alpha\ge 0$ and $p,q\in \{1,\ldots,n-1\}$ with $p+q\le n$ be given. Then, for any $u \in S^{n-1}$ and any fixed $M\in G(n,p)$ we have that
	\begin{equation}\label{eq:roatatFixedAxisSubspDet}
		\int_{G(\operatorname{span} u,q)} [L,M]^\alpha\, \nu_q^{\operatorname{span}{u}}(dL)= a({n,p,q,\alpha})[u,M]^\alpha
	\end{equation}
	with 
	\[
	a({n,p,q,\alpha})=\prod_{i=1}^{p}
	\frac{\Gamma(\frac{n-i}{2})\Gamma(\frac{n-q-i+\alpha+1}{2})}
	{\Gamma(\frac{n-i+\alpha}2)\Gamma(\frac{n-q-i+1}2)}.
	\]

\label{ThmGeneral}
Fix $n\geq 2$, $q\in\{1,\ldots,n-1\}$, $\gamma\in\{0,\ldots,q-1\}$,  and let $H: A(n,n-q+\gamma) \rightarrow [0,\infty)$ be a measurable and rotation invariant function. Then 
\begin{align*}
    &\int_{G(n,q)}
		\int_{A(n,n-q+\gamma)}
		f(E \cap L) H(E) \ \mu_{n-q+\gamma}(dE) \ \nu_q(dL)
  \\&=D(n,q,\gamma)
		\int_{A(n, \gamma)}
		f( E) d(o,E)^{-(n-q)} J_H(d(o,E)) \ \mu_\gamma(dE)
\end{align*}
for all measurable $f: A(n,\gamma) \rightarrow [0,\infty)$. Here, 
	\begin{equation}\label{eq:defJ}
		J_H(r) =\int_0^1
		H_I(r z) z^{ q}(1-z^2)^{ \frac{n-q}{2}-1}
		\ dz,
	\end{equation}
and the constant is given by
	\begin{equation}
		D(n,q,\gamma)=  \frac{\omega_{\gamma+1}\omega_{q-\gamma}
			\omega_{n-q}
		}{\omega_{n-(q-\gamma)+1}\omega_{n-\gamma}}.
  \label{eq:Ddef}
	\end{equation}

\label{cor:Hindicator}
	Fix $n\geq 2$, $q\in\{1,\ldots,n-1\}$, $\gamma\in\{0,\ldots,q-1\}$, and $h>0$. Then
	\begin{align*}
		&\int_{G(n,q)}
		\int_{[hB^n]_{n-q+\gamma}}
		f(E \cap L)\, \mu_{n-q+\gamma}(dE) \, \nu_q(dL)
		\\&=D(n,q,\gamma)
		\int_{A(n,\gamma)} f(E) d(o,E)^{-(n-q)} J(d(o,E)) 
  \, \mu_\gamma(dE),
	\end{align*}
	where $J=J_{H_h}$ is given by \eqref{eq:JHr} and  where $D(n,q,\gamma)$ is the constant given in Theorem \ref{ThmGeneral}.

\label{thm:Hconstant}
	Fix $n\geq 2$, $q\in\{1,\ldots,n-1\}$ and $\gamma\in\{0,\ldots,q-1\}$. Then  
	\begin{align*}
		&\int_{G(n,q)}
		\int_{A(n,n-q+\gamma)}
		f(E \cap L)
		\,\mu_{n-q+\gamma} (dE)\,\nu_q(dL)
		\\&=
  \tilde D(n,q,\gamma) \int_{A(n,\gamma)} f(E) d(o,E)^{-(n-q)}  \ \mu_\gamma(dE)
	\end{align*}
 for all measurable functions $f:A(n, \gamma) \rightarrow [0,\infty)$. Here, 
	\begin{equation*} 
 \tilde D(n,q,\gamma)=
\frac{\omega_{n+1}\omega_{\gamma+1}
     \omega_{q-\gamma}}
     {\omega_{n-(q-\gamma)+1} 
     \omega_{n-\gamma}\omega_{q+1}}. 
\end{equation*}

\label{ThmGeneral1}
Fix $n\geq 2$,  $q\in\{1,\ldots,n-1\}$, $\gamma\in\{0,\ldots,q-1\}$  and 
$L_0\in G(n,q)$. Let $H: A(n,n-q+\gamma) \rightarrow [0,\infty)$ be a 
rotation invariant, measurable function. Then 
\begin{align}  \label{eq:new}
		\int_{A(n,n-q+\gamma)}
		f(E \cap L_0) H(E) \ \mu_{n-q+\gamma}(dE)=
  \frac
  {\omega_{\gamma+1}\omega_{n-q}}{\omega_{n-(q-\gamma)+1}}
		\int_{A(L_0, \gamma)}
		f(E) J_H(d(o,E)) \ \mu_\gamma^{L_0}(dE)
\end{align}
for all measurable $f: A(L_0,\gamma) \rightarrow [0,\infty)$. Here, $J_H$ is given in Theorem \ref{ThmGeneral}.

\label{thm:Application}
	In the set-up just introduced, the probability density $f_{n,q,\gamma}(\delta)$ of the random variable $d(o,E\cap L)$ is given by
	\begin{align*}
		f_{n,q,\gamma}(\delta) = (q-\gamma){\omega_{\gamma+1}\omega_{n-q}\over\omega_{n-(q-\gamma)+1}}\begin{cases}
			{\omega_{n+1}\over\omega_{q+1}\omega_{n-q}}\delta^{q-\gamma-1} &: 0\le \delta\leq 1\\
			{1\over 2}\delta^{q-\gamma-1}B({1\over \delta^2};{q+1\over 2},{n-q\over 2}) &: \delta>1.
		\end{cases}
	\end{align*}

Fix $\delta>0$ and consider the probability of the event $d(o,E\cap L)\leq\delta$. Using Corollary \ref{cor:Hindicator} with $h=1$, we obtain
	\begin{align*}
		\mathbb{P}[d(o,E\cap L)\leq\delta] &= {1\over\kappa_{q-\gamma}}\int_{G(n,q)}\int_{A(n,n-q+\gamma)}1_{\{d(o,E)\leq 1\}}\,1_{\{d(o,E\cap L)\leq\delta\}}\,\mu_{n-q+\gamma}(dE)\nu_q(dL)\\
		&={D(n,q,\gamma)\over\kappa_{q-\gamma}}\int_{A(n,\gamma)}1_{\{d(o,E)\leq\delta\}}d(o,E)^{-(n-q)}J_{H_1}(d(o,E))\,\mu_\gamma(dE),
	\end{align*}
 with
	$$
	J_{H_1}(r) = \begin{cases}
		{\omega_{n+1}\over\omega_{q+1}\omega_{n-q}} &: r\leq 1\\
		{1\over 2}B({1\over r^2};{q+1\over 2},{n-q\over 2}) &: r>1.
	\end{cases}
	$$
	We now apply the decomposition \eqref{eq:DefMuq}, use $d(o,L+x)=\|x\|$ whenever $x\in L^\perp$,  
    and then introduce spherical coordinates in 
    $L^\perp$ to see that 
	\begin{align*}
		&\mathbb{P}[d(o,E\cap L)\leq\delta]\\

		&={D(n,q,\gamma)\over\kappa_{q-\gamma}}
  \int_{G(n,\gamma)}\int_{L^\perp}1_{\{\|x\|\leq\delta\}}\|x\|^{-(n-q)}J_{H_1}(\|x\|)\,\lambda_{L^\perp}(dx)\nu_\gamma(dL)\\
		&={D(n,q,\gamma) \omega_{n-\gamma}\over\kappa_{q-\gamma}}\int_0^\delta r^{q-\gamma-1}J_{H_1}(r)\,dr.
	\end{align*}
	Taking the derivative with respect to $\delta$ in the last expression, inserting the value of the constant $D(n,q,\gamma)$ of Theorem \ref{ThmGeneral} and then using \eqref{eq:KappanOmegan} yields the result.

\label{cor:Sphere}
Fix $n\geq 2$, $q\in\{1,\ldots,n-1\}$, $\gamma\in\{0,\ldots,q-1\}$ and let $f: A(n,\gamma) \rightarrow [0,\infty)$ be a measurable, rotation invariant and bounded function.
Then
	\begin{align*}
		\int_{G(n,q)}   &\int_{G(n,n-q+\gamma)} \int_{S^{n-1} \cap M^\perp }
		f((M+hu) \cap L)
		\ \mathcal{H}^{q-\gamma-1}(du)
		\ \nu_{n-q+\gamma}(dM)  \ \nu_q (dL)
		\\&
		=
		D(n,q,\gamma)
	{\omega_{n-\gamma}}h^{\gamma+1}
		\int_h^\infty 
		f_I(r) r^{-(\gamma+2)}  \Big( 1-\frac{h^2}{r^2} \Big) ^{\frac{n-q}{2}-1}
		\ dr
	\end{align*}
 for almost every $h>0$.

Let $f:A(n, \gamma) \rightarrow [0, \infty)$ satisfy the above assumptions and define the function $F:(0,\infty)\to [0, \infty)$ by 
	\begin{align*}
		F(h)
		&=
		D(n,q,\gamma)\int_{A(n,\gamma)} f(E) d(o,E)^{-(n-q)} J_{H_h}(d(o,E)) \ \mu_\gamma(dE)
		\\& =D(n,q,\gamma)
	\omega_{n-\gamma} \int_0^\infty f_I(r) r^{q-\gamma-1}
		J_{H_h}(r) \ dr,
	\end{align*}
	with $D(n,q,\gamma)$ as in Theorem \ref{ThmGeneral} and $J_{H_h}$ given by \eqref{eq:JHr}. Since
	\begin{align*}
		\frac{\partial}{\partial h}
		J_{H_h}(r)=
		\begin{cases}
			0 &: 0\le r < h
			\\
			r^{-q-1} h^q \Big( 1-\frac{h^2}{r^2} \Big) ^{\frac{n-q}{2}-1} &: r>h, 
		\end{cases}
	\end{align*}
	we conclude that $F(h)$ is differentiable for almost all $h>0$
    with derivative
	\begin{equation*}
		F'(h)
		=
		D(n,q,\gamma)
	\omega_{n-\gamma} 
		\int_h^\infty 
		f_I(r) r^{-\gamma-2} h^q \Big( 1-\frac{h^2}{r^2} \Big) ^{\frac{n-q}{2}-1}
		\ dr.
	\end{equation*}
    Here, differentiation under the integral sign can be justified as follows.
For fixed $r>0$, the integrand $g(r,h)=f_I(r)r^{q-\gamma-1} J_{H_h}(r)$ is absolutely continuous as function of $h$. Since $(r,h)\mapsto \partial /(\partial h) g(r,h)$ is integrable on $(0,\infty)\times (a,b)$ for any $0<a<b<\infty$, Fubini's theorem and Lebesgue differentiation theorem imply 
\[
F'(h)=\frac{d}{dh}\int_1^h \int_0^\infty \frac{\partial}{\partial h}  g(r,t)drdt=\int_0^\infty \frac{\partial}{\partial h}  g(r,h)dr
\]
for a.e.~$h\in (a,b)$, yielding the intermediate assertion. 

     On the other hand,  Theorem \ref{ThmGeneral}, relation \eqref{eq:DefMuq} and spherical integration yield
	\begin{equation*}
		F(h)
		=
		\int_{G(n,q)}   \int_{G(n,n-q+\gamma)} \int_{S^{n-1} \cap M^\perp }
		\int_0^h 
		f((M+ru) \cap L)
		r^{q-\gamma-1}
		\ dr \ \mathcal{H}^{q-\gamma-1}(du)
		\ \nu_{n-q+\gamma}(dM) \nu_q (dL),
	\end{equation*}
	and hence
	\begin{equation*}
		F'(h)
		=
		\int_{G(n,q)}   \int_{G(n,n-q+\gamma)} \int_{S^{n-1} \cap M^\perp }
		f((M+hu) \cap L)
		h^{q-\gamma-1}
		\ \mathcal{H}^{q-\gamma-1}(dy)
		\ \nu_{n-q+\gamma}(dM) \nu_q (dL)
	\end{equation*}
    for almost every $h>0$ due to the Lebesgue differentiation theorem.
	This completes the proof of the lemma.

\label{thm:Application2}
			Fix $n\geq 2$, $q\in\{1,\ldots,n-1\}$ and $\gamma\in\{0,\ldots,q-1\}$. Let $L$ be a random linear subspace with distribution $\nu_q$ and let $E$ be a stochastically independent random affine subspace, tangent to the unit sphere, with distribution $\sigma_{n-q+\gamma}$ given by \eqref{eq:randomDensFlatSphere}.
			Then the random variable $d(o,E\cap L)^{-2}$ has a beta distribution with shape parameters 
			 \[
			 a=\frac{\gamma+1}2 \qquad\text{ and  }\qquad  b=\frac{n-q}2.
			 \]
			 More explicitly, 
			\begin{align*}
				g_{n,q,\gamma}(r) =   {\omega_{\gamma+1}\omega_{n-q}\over \omega_{n-(q-\gamma)+1}}\,
				r^{-(\gamma+2)}  \Big( 1-\frac{1}{r^2} \Big) ^{\frac{n-q}{2}-1}\,1_{\{r>1\}}
			\end{align*}
			is 	a  probability density for 
			$d(o,E\cap L)$.

Let $X$ be a beta-distributed random variable on $(0,1)$  with shape parameters $a,b>0$. Then $X^{-1/2}$ has tail probabilities 
	     \begin{align}\nonumber
	     1-F_{X^{-1/2}}(t)&= \mathbb{P}\Big[X\leq{1\over t^2}\Big] 
	     \\\nonumber
	     &= \frac1{B(a,b)}\int_{0}^{1/t^2}x^{a-1}(1-x)^{b-1}\ dx 
	     \\\label{eq:betadist}
	     &= \frac2{B(a,b)}\int_{t}^{\infty}r^{-2a-1}\Big(1-\frac1{r^2}\Big)^{b-1}\ dr, \qquad t>1. 
	     \end{align}

		On the other hand, applying Lemma \ref{cor:Sphere} with $f(E)= 1_{\{d(o,E) \geq t \}}$ yields 
			\begin{align}\nonumber 
				\frac{1}{\omega_{q-\gamma}}    \int_{G(n,q)}   &\int_{G(n,n-q+\gamma)} \int_{S^{n-1} \cap M^\perp }
				1_{\{d(o,(M+hu) \cap L) \geq t\}}
				\ \mathcal{H}^{q-\gamma-1}(du)
				\ \nu_{n-q+\gamma}(dM) \nu_q (dL)
				\\&
				=
				D(n,q,\gamma)\frac{\omega_{n-\gamma} }
				{
					\omega_{q-\gamma}
				}h^{\gamma+1}
				\int_h^\infty 
				1_{\{r \geq t \}} r^{-(\gamma+2)}  \Big( 1-\frac{h^2}{r^2} \Big) ^{\frac{n-q}{2}-1}
				\ dr\label{eq:onemore}
			\end{align}
			for almost all $h>0$.
			Using monotone convergence, one can show that both sides of \eqref{eq:onemore} are  continuous in $h$, so this relation extends to all $h>0$. Letting $h=1$, we see that the tail distributions of $d(o,E \cap L)$ are proportional to 
			\[
			\int_{t}^\infty r^{-(\gamma+2)}  \Big( 1-\frac{1}{r^2} \Big) ^{\frac{n-q}{2}-1}
			\ dr, \qquad t>1. 
			\]
			A comparison with \eqref{eq:betadist} shows the first claim. The explicit density $g_{n,q,\gamma}$ is obtained by differentiation
			of \eqref{eq:onemore} when $h=1$.

Given $E\in A(n,q)$, $q\in\{0,\ldots,n\}$, we will write $\operatorname{lin}(E)$ for the linear subspace in $G(n,q)$ parallel to $E$. In other words, $\operatorname{lin}(E)=E-x$ for all $x\in E$. 

For the proof of Theorem \ref{ThmGeneral}, fix  $n\geq 1$, $q\in\{1,\ldots,n-1\}$ and $\gamma\in\{0,\ldots,q-1\}$, and let $f: A(n, \gamma)\to [0,\infty)$ be a measurable function. Due to Lemma \ref{Lemma:EnoughRotational}, we may assume without loss of generality that $f$ is rotation invariant. The integral of interest is
\begin{equation*}
	I=
	\int_{G(n,q)}\int_{A(n,n-q+\gamma)} f(E \cap L) H(E)  \ \mu_{n-q+\gamma}(dE) \ \nu_{q}(dL).
\end{equation*}
 First note that $I$ is indeed well-defined as for $\nu_q$-almost all $L \in G(n,q)$ and $\mu_{n-q+\gamma}$-almost all $E \in A(n,n-q+\gamma)$ we have $\dim (E \cap L)=\gamma$. This follows from 
 \cite[Lem.~13.2.1]{SchWeil2008}, applied 
 to $L$ and $L'=\operatorname{lin}(E)$. 

 Define the function $g: A(n,q) \times A(n,n-q+\gamma) \to \mathbb{R}$ by
\begin{align*}
	g(E_1,E_2) =  f\big(\operatorname{lin} (E_1) \cap E_2\big) 1_{\{d(o,E_1)\leq 1 \}}H(E_2),
\end{align*}
where we let $f(\operatorname{lin} (E_1) \cap E_2)=0$ if $\dim (\operatorname{lin} (E_1) \cap  E_2)\ne \gamma$. Definition \eqref{eq:DefMuq} implies 
\begin{equation*}
	I=\frac{1}{\kappa_{n-q}}
	\int_{A(n,q)}\int_{A(n,n-q+\gamma)} g(E_1,E_2) \, \mu_{n-q+\gamma}(dE_2) \mu_{q}(dE_1).
\end{equation*}
Applying \cite[Thm.~7.2.8]{SchWeil2008} with $s_1=q$ and $s_2 = n-q+\gamma$ yields 
\begin{align}
	I
	=
	\frac{\Bar{b}}{\kappa_{n-q} }
	\int_{A(n,\gamma)} 
	\int_{A(E,q)} 
	\int_{A(E,n-q+\gamma)}
	& g(E_1,E_2) [\operatorname{lin}(E_1), \operatorname{lin}(E_2)]^{\gamma+1} \nonumber
	\\& \times \ \mu_{n-q+\gamma}^E (dE_2)  \ \mu_{q}^E(dE_1) \  \mu_\gamma(dE),  
	\label{eq:dummy1}
\end{align}
with the constant $\Bar{b}$ given by
\begin{equation}
	\Bar{b}
	=
	b_{n,n-\gamma} \frac{
		b_{n-\gamma,n-q}
		b_{n-\gamma, q-\gamma}
	}{ 
		b_{n,n-q}
		b_{n,q-\gamma}},\qquad b_{i,j} = {\omega_{i-j+1}\cdots\omega_{i}\over\omega_1\cdots\omega_j},\ i\in \mathbb{N},j\in\{1,\ldots,i\}.
  \label{eq:ovB}
\end{equation}
Expanding \eqref{eq:dummy1} by decomposing the measure $\mu_{\gamma}$ according to \eqref{eq:DefMuq},
applying \cite[Eq.~(13.14)]{SchWeil2008} and Tonelli's theorem yields 
\begin{equation} 
	I
	=
	\frac{\Bar{b}}{\kappa_{n-q} }
	\int_{G(n, \gamma)}
	I_1(L_0,f) \ \nu_\gamma(dL_0) \label{eq:dummy1.5}
\end{equation}
with
\begin{align}
	I_1(L_0,f) \nonumber
	& =
	\int_{G(L_0,q)}
	\int_{G(L_0,n-q+\gamma)} 
	\int_{L_0^\perp }
	f((M+t)\cap L) 
   1_{\{d(o,L+t) \leq 1\}} H(M+t) \nonumber
	\\& 
	\hspace{4cm} \times \ \lambda_{L_0^\perp}(dt)  [M, L]^{\gamma+1}\ \nu_{n-q+\gamma}^{L_0} (dM)  
	\ \nu_{q}^{L_0}(dL). \nonumber
\end{align}
Since
\begin{equation*}
	\int_{G(L_0,p)} h(L) \ \nu_p^{L_0}(dL)
	=
	\int_{G(L_0^\perp, p-\gamma)} h(L_0+L) \ \nu_{p-\gamma}^{L_0^\perp}(dL)
\end{equation*}
for all $L_0 \in G(n, \gamma)$ and for any measurable function $h:G(L_0,p)\to[0,\infty)$ and integers $\gamma < p <n$, we conclude 
\begin{equation}
	\begin{split}
		I_1(L_0,f) & = 
		\int_{G(L_0^\perp,q-\gamma)} 
		\int_{G(L_0^\perp,n-q)} 
		\int_{L_0^\perp }
		f\Big(\big((M+t)\cap L\big)+ L_0 \Big) 1_{\{d(o,L+t) \leq 1\}} \\& 
		\qquad \qquad \times H(M+L_0+t) \ \lambda_{L_0^\perp}(dt) 
  [M, L]^{\gamma+1}
  \ \nu_{n-q}^{L_0^\perp} (dM)  
		\ \nu_{q-\gamma}^{L_0^\perp}(dL),    \label{eq:dummy2}
	\end{split}
\end{equation}
where we also have used $(M+L_0+t) \cap (L+L_0) = \big( (M+t) \cap L \big)+L_0$,  $d(o,L+L_0+t)=d(o,L+t)$ and $[M+L_0, L+L_0]= [M,L]$. 


Now consider \eqref{eq:dummy2} for fixed  $L_0 \in G(n, \gamma)$, $M \in G(L_0^\perp, n-q)$ and $L \in G(L_0^\perp, q-\gamma)$. 
As $f$ and $H$ are both rotation invariant, we may write
\begin{align*}
	f\big(((M+t)\cap L)+ L_0\big) 
	&=
	f_I\big( d(o, (M+t) \cap L) \big),
	\\
	H(M+L_0+t)&= H_I(\|t|M^\perp \|),
\end{align*}
with $f_I$ and $H_I$ satisfying \eqref{eq:fI}. Thus, we may identify $L_0^\perp$ with $\mathbb{R}^{n-\gamma}$ and conclude that
\begin{align}
	I_1(L_0,f)
	&=
	\int_{G(n-\gamma,q-\gamma)} 
	\int_{G(n-\gamma,n-q)} I_2(L,M)
	[M,L]^{\gamma+1}  \nu_{n-q} (dM) 
	\ \nu_{q-\gamma}(dL),
 \label{eq:I1in_Rn-q}
\end{align}












with
\begin{align*}
	I_2(M,L)
	&=
	\int_{\mathbb{R}^{n-\gamma}}
	f_I(d(o,(M+t)\cap L))    1_{\{d(o,L+t) \leq 1\}} H_I(\|t|M^\perp \|)
	\ \lambda_{ {n-\gamma}}(dt)
	\\
	&=
	\int_{M} \int_{M^\perp} 
	f_I( d(o,(M+x)\cap L)) 
	H_I(\|x \|)  1_{\{d(o,L+x+y) \leq 1\}} \ 
	\ \lambda_{M^\perp}(dx) \ \lambda_M(dy) 
\end{align*}
for $M \in G(n-\gamma, n-q)$ and $L \in G(n-\gamma,q-\gamma)$. Applying \eqref{eq:IntroProjectionFormula} to the Lebesgue integral over $M^\perp$ we get
\begin{align*}
	I_2(M,L) &= [M,L] 
	\int_{M} \int_{L}
	f_I( d(o,(M+t)\cap L)) 
	H_I(\|t|M^\perp  \|)  1_{\{d(o,L+t|M^\perp+y) \leq 1\}} \ 
	\ \lambda_{L}(dt) \ \lambda_M(dy) 
	\\
	&
	=   \int_{L}  f_I( d(o,(M+t)\cap L))  H_I(\|t|M^\perp  \|) I_3(M,L,t) \ \lambda_{L}(dt),
\end{align*}
where we first used the fact that 
$M+t|M^\perp=M+t$ holds for any $t \in L$, and then Tonelli's theorem.  
Here, 
\[
I_3(M,L,t) =[M,L]
 \int_{M}  
	1_{\{\|(t| M^\perp)|L^\perp+y|L^\perp \| \leq 1\}} \ 
\lambda_M(dy).
\]
Another application of  \eqref{eq:IntroProjectionFormula} 
reveals that 
